// Bills list in the UBM product layout. Server-side paging: the grid shows one
// page of getBills; page number and size go back to Appsmith through
// onPageChange, which re-runs the query. Selection is kept here across pages.
var DOWN = '<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"/><polyline points="7 10 12 15 17 10"/><line x1="12" y1="15" x2="12" y2="3"/></svg>';
var INFO = '<svg class="info" width="14" height="14" viewBox="0 0 24 24"><circle cx="12" cy="12" r="11" fill="currentColor"/><rect x="11" y="10" width="2" height="7" fill="#fff"/><rect x="11" y="6.5" width="2" height="2" fill="#fff"/></svg>';
var BULK_MAX = 25;

function p2(n){ return (n < 10 ? '0' : '') + n; }
function fmtDate(v){
  if (!v) return '';
  var d = new Date(v);
  if (isNaN(d)) return String(v);
  return p2(d.getMonth() + 1) + '/' + p2(d.getDate()) + '/' + d.getFullYear();
}
function fmtMoney(v){
  if (v === null || v === undefined || v === '') return '';
  var n = Number(v);
  if (isNaN(n)) return String(v);
  var s = Math.abs(n).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  return (n < 0 ? '-$' : '$') + s;
}
// "MM/DD/YYYY" strings sort by date, not as text.
function dateKey(v){
  if (!v) return 0;
  var m = /^(\d{2})\/(\d{2})\/(\d{4})$/.exec(String(v));
  if (m) return Number(m[3] + m[1] + m[2]);
  var d = new Date(v);
  return isNaN(d) ? 0 : d.getTime();
}
function dateCmp(a, b){ return dateKey(a) - dateKey(b); }
function numCmp(a, b){ return (Number(a) || 0) - (Number(b) || 0); }

// ---- selection (kept across pages) ----
var sel = {};          // bill_id -> true, when not in "all" mode
var allMode = false;   // Select All: every bill that matches the filters
var excl = {};         // bill_ids unticked while in "all" mode

function idOf(r){ return r && r.bill_id; }
function isSel(id){ return allMode ? !excl[id] : !!sel[id]; }
function nKeys(o){ return Object.keys(o).length; }
function selCount(){ return allMode ? Math.max(0, total(M) - nKeys(excl)) : nKeys(sel); }
function toggle(id){
  if (id == null) return;
  if (allMode) { if (excl[id]) delete excl[id]; else excl[id] = true; }
  else { if (sel[id]) delete sel[id]; else sel[id] = true; }
  selChanged();
}
function setPage(on){
  rows(M).forEach(function(r){
    var id = idOf(r); if (id == null) return;
    if (allMode) { if (on) delete excl[id]; else excl[id] = true; }
    else { if (on) sel[id] = true; else delete sel[id]; }
  });
  selChanged();
}
function selectAll(){ allMode = true; excl = {}; sel = {}; selChanged(); }
function clearAll(){ allMode = false; excl = {}; sel = {}; selChanged(); }
function pageState(){
  var r = rows(M).filter(function(x){ return idOf(x) != null; });
  var n = r.filter(function(x){ return isSel(idOf(x)); }).length;
  return n === 0 ? 'none' : (n === r.length ? 'all' : 'some');
}
function selChanged(){
  drawSelBar();
  if (gridApi) gridApi.refreshCells({ columns: ['__sel'], force: true });
  if (gridApi) gridApi.forEachNode(function(n){ if (n.data) n.setSelected(isSel(idOf(n.data)), false, 'api'); });
  drawHeaderBox();
}

// ---- header checkbox ----
var headerBox = null;
function HeaderSel(){}
HeaderSel.prototype.init = function(){
  this.e = document.createElement('label');
  this.e.className = 'cbwrap';
  this.e.innerHTML = '<input type="checkbox" class="cb" title="Select this page" />';
  headerBox = this.e.querySelector('input');
  headerBox.addEventListener('click', function(ev){
    ev.stopPropagation();
    setPage(pageState() !== 'all');
  });
  drawHeaderBox();
};
HeaderSel.prototype.getGui = function(){ return this.e; };
HeaderSel.prototype.refresh = function(){ drawHeaderBox(); return true; };
function drawHeaderBox(){
  if (!headerBox) return;
  var s = pageState();
  headerBox.checked = s === 'all';
  headerBox.indeterminate = s === 'some';
}

function VendorHeader(){}
VendorHeader.prototype.init = function(p){
  var self = this;
  this.p = p;
  this.e = document.createElement('div');
  this.e.className = 'hdr';
  this.e.innerHTML = '<span class="ht">Vendor</span>' + INFO + '<span class="sorti"></span>';
  this.e.querySelector('.info').setAttribute('title', 'Vendor display name, or the vendor code when no display name is set');
  this.e.addEventListener('click', function(ev){ p.progressSort(ev.shiftKey); });
  p.column.addEventListener('sortChanged', function(){ self.drawSort(); });
  this.drawSort();
};
VendorHeader.prototype.drawSort = function(){
  var s = this.p.column.getSort();
  this.e.querySelector('.sorti').textContent = s === 'asc' ? '▴' : (s === 'desc' ? '▾' : '↕');
};
VendorHeader.prototype.getGui = function(){ return this.e; };
VendorHeader.prototype.refresh = function(){ return true; };

function selRenderer(p){
  if (!p.data) return '';
  return '<label class="cbwrap"><input type="checkbox" class="cb" ' + (isSel(idOf(p.data)) ? 'checked' : '') + ' /></label>';
}
function dlRenderer(p){
  if (!p.data) return '';
  return '<button class="act" title="Download bill file">' + DOWN + '</button>';
}

var R = 'num';
var COLS = [
  { colId: '__sel', headerComponent: HeaderSel, width: 56, minWidth: 56, maxWidth: 56, sortable: false, resizable: false, cellRenderer: selRenderer, cellClass: 'ctr' },
  { headerName: 'Vendor', field: 'Vendor', headerComponent: VendorHeader, flex: 1.4, minWidth: 150, tooltipField: 'Vendor' },
  { headerName: 'Invoice Date', field: 'Invoice Date', flex: 1, minWidth: 115, comparator: dateCmp, cellClass: R, headerClass: R },
  { headerName: 'Billing ID', field: 'Billing ID', flex: 1.2, minWidth: 130, tooltipField: 'Billing ID' },
  { headerName: 'Billing Start Date', field: 'Billing Start Date', flex: 1, minWidth: 135, comparator: dateCmp, cellClass: R, headerClass: R },
  { headerName: 'Billing End Date', field: 'Billing End Date', flex: 1, minWidth: 130, comparator: dateCmp, cellClass: R, headerClass: R },
  { headerName: 'Current Charges', field: 'Current Charges', flex: 1, minWidth: 130, comparator: numCmp, valueFormatter: function(p){ return fmtMoney(p.value); }, cellClass: R, headerClass: R },
  { headerName: 'Total Amount Due', field: 'Total Amount Due', flex: 1, minWidth: 140, comparator: numCmp, valueFormatter: function(p){ return fmtMoney(p.value); }, cellClass: R, headerClass: R },
  { headerName: 'Pay Amount', field: 'Pay Amount', flex: 1, minWidth: 115, comparator: numCmp, valueFormatter: function(p){ return fmtMoney(p.value); }, cellClass: R, headerClass: R },
  { headerName: 'Marked For Payment', field: 'Marked For Payment', flex: 1.1, minWidth: 150, comparator: dateCmp, valueFormatter: function(p){ return fmtDate(p.value); }, cellClass: R, headerClass: R },
  { colId: '__dl', headerName: '', width: 64, minWidth: 64, maxWidth: 64, sortable: false, resizable: false, cellRenderer: dlRenderer, cellClass: 'ctr' }
];

var gridApi = null;
var lastSig = '';
var lastTotal = null;
var M = {};

function rows(m){ return (m && Array.isArray(m.data)) ? m.data : []; }
function total(m){ var t = Number(m && m.total); return isNaN(t) ? 0 : t; }
function page(m){ return Math.max(1, Number(m && m.page) || 1); }
function size(m){ return Number(m && m.pageSize) || 20; }
function pages(m){ return Math.max(1, Math.ceil(total(m) / size(m))); }

function sig(m){
  var r = rows(m);
  return (m && m.isLoading ? 'L' : '') + r.length + ':' + (r[0] && r[0].bill_id) + ':' + (r[r.length - 1] && r[r.length - 1].bill_id);
}

function goTo(p, s){
  appsmith.updateModel({ page: p, pageSize: s || size(M) });
  appsmith.triggerEvent('onPageChange');
}

function notice(msg){
  appsmith.updateModel({ notice: msg });
  appsmith.triggerEvent('onNotice');
}

function drawSelBar(){
  document.getElementById('selCount').textContent = selCount().toLocaleString() + ' of ' + total(M).toLocaleString();
}

function pageList(p, n){
  if (n <= 7) { var a = []; for (var i = 1; i <= n; i++) a.push(i); return a; }
  if (p <= 4) return [1, 2, 3, 4, 5, '…', n];
  if (p >= n - 3) return [1, '…', n - 4, n - 3, n - 2, n - 1, n];
  return [1, '…', p - 1, p, p + 1, '…', n];
}

function drawPager(){
  var p = page(M), n = pages(M);
  var html = '<button class="pg nav" data-go="' + (p - 1) + '"' + (p <= 1 ? ' disabled' : '') + ' title="Previous page">&lsaquo;</button>';
  pageList(p, n).forEach(function(x){
    if (x === '…') html += '<span class="gap">…</span>';
    else html += '<button class="pg' + (x === p ? ' cur' : '') + '" data-go="' + x + '">' + x.toLocaleString() + '</button>';
  });
  html += '<button class="pg nav" data-go="' + (p + 1) + '"' + (p >= n ? ' disabled' : '') + ' title="Next page">&rsaquo;</button>';
  document.getElementById('pages').innerHTML = html;
  document.getElementById('size').value = String(size(M));
  drawSelBar();
}

function csv(){
  var cols = COLS.filter(function(c){ return c.field; });
  function q(v){ v = v == null ? '' : String(v); return /[",\n]/.test(v) ? '"' + v.replace(/"/g, '""') + '"' : v; }
  var out = [cols.map(function(c){ return q(c.headerName); }).join(',')];
  gridApi.forEachNodeAfterFilterAndSort(function(n){
    out.push(cols.map(function(c){ return q(c.valueFormatter ? c.valueFormatter({ value: n.data[c.field] }) : n.data[c.field]); }).join(','));
  });
  return out.join('\n');
}

function bulkDownload(){
  var ids;
  if (allMode) {
    if (selCount() > rows(M).length) {
      notice('Bulk Download opens up to ' + BULK_MAX + ' bill files at a time. Tick the bills you need, or narrow the filters first.');
      return;
    }
    ids = rows(M).map(idOf).filter(function(id){ return id != null && !excl[id]; });
  } else {
    ids = Object.keys(sel).map(Number);
  }
  if (!ids.length) { notice('Select one or more bills first.'); return; }
  if (ids.length > BULK_MAX) { notice('Bulk Download opens up to ' + BULK_MAX + ' bill files at a time; ' + ids.length + ' are selected.'); return; }
  appsmith.updateModel({ bulkIds: ids });
  appsmith.triggerEvent('onBulkDownload');
}

function onCellClicked(e){
  if (!e.data) return;
  var col = e.column && e.column.getColId();
  if (col === '__sel') { toggle(idOf(e.data)); return; }
  if (col === '__dl') {
    appsmith.updateModel({ fileBillId: e.data.bill_id });
    appsmith.triggerEvent('onFileDownload');
    return;
  }
  appsmith.updateModel({ openBillId: e.data.bill_id });
  appsmith.triggerEvent('onRowOpen');
}

function render(){
  var div = document.getElementById('myGrid');
  div.innerHTML = '';
  gridApi = agGrid.createGrid(div, {
    columnDefs: COLS,
    rowData: rows(M),
    domLayout: 'autoHeight',
    defaultColDef: { resizable: true, sortable: true, minWidth: 80 },
    rowSelection: 'multiple',
    suppressRowClickSelection: true,
    suppressCellFocus: true,
    popupParent: document.body,
    tooltipShowDelay: 400,
    rowClassRules: { 'deleted': function(p){ return !!(p.data && p.data.deleted_at); } },
    overlayNoRowsTemplate: '<span class="empty">No bills found</span>',
    overlayLoadingTemplate: '<span class="empty">Loading bills…</span>',
    onCellClicked: onCellClicked
  });
  if (M.isLoading) gridApi.showLoadingOverlay();
  lastSig = sig(M);
  selChanged();
}

function update(m){
  M = m || {};
  // A new total means the filters or search changed: clear the selection and
  // start again from page 1.
  if (!M.isLoading && M.total != null) {
    var t = total(M);
    if (lastTotal !== null && t !== lastTotal) {
      lastTotal = t;
      clearAll();
      if (page(M) > 1) { goTo(1); return; }
    }
    lastTotal = t;
  }
  drawPager();
  if (!gridApi){ render(); return; }
  var s = sig(M);
  if (s === lastSig) return;
  lastSig = s;
  if (M.isLoading){ gridApi.showLoadingOverlay(); return; }
  gridApi.setGridOption('rowData', rows(M));
  if (!rows(M).length) gridApi.showNoRowsOverlay(); else gridApi.hideOverlay();
  selChanged();
  if (!rows(M).length && page(M) > 1 && total(M) > 0) goTo(1);
}

appsmith.onReady(function(){
  document.getElementById('pages').addEventListener('click', function(e){
    var b = e.target.closest('[data-go]');
    if (!b || b.disabled) return;
    var p = Number(b.getAttribute('data-go'));
    if (p >= 1 && p <= pages(M) && p !== page(M)) goTo(p);
  });
  document.getElementById('goto').addEventListener('keydown', function(e){
    if (e.key !== 'Enter') return;
    var p = Math.min(pages(M), Math.max(1, parseInt(e.target.value, 10) || 1));
    e.target.value = '';
    if (p !== page(M)) goTo(p);
  });
  document.getElementById('size').addEventListener('change', function(e){ goTo(1, Number(e.target.value)); });
  document.getElementById('selAll').addEventListener('click', function(e){ e.preventDefault(); selectAll(); });
  document.getElementById('clrAll').addEventListener('click', function(e){ e.preventDefault(); clearAll(); });
  document.getElementById('bulk').addEventListener('click', function(e){ e.preventDefault(); bulkDownload(); });
  document.getElementById('dl').addEventListener('click', function(e){
    e.preventDefault();
    if (!gridApi) return;
    appsmith.updateModel({ csv: csv() });
    appsmith.triggerEvent('onCsvDownload');
  });
  update(appsmith.model);
  appsmith.onModelChange(update);
});
